document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
document.getElementById('quote-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.target);const viz=data.get('viz')?'3D-візуалізація: так, безкоштовно':'';const text=`Вітаю, Cutline! Хочу розрахувати вартість обклеювання.\nАвто: ${data.get('car')}\nОбсяг: ${data.get('scope')}\nКолір / фактура: ${data.get('finish')||'Потрібна консультація'}${viz?'\n'+viz:''}`;const status=event.target.querySelector('.form-status');try{await navigator.clipboard.writeText(text);status.textContent='Запит скопійовано. Його можна надіслати студії, щойно з’являться контакти.';}catch{const field=document.getElementById('request-text');field.hidden=false;field.value=text;field.select();status.textContent='Ваш запит готовий. Скопіюйте текст нижче.';}});

