(()=>{const heads=[...document.querySelectorAll('.hero .copy h1, main>section:not(.hero) h2')];if(!heads.length)return;heads.forEach(h=>{if(!h.hasAttribute('aria-label'))h.setAttribute('aria-label',h.innerText.replace(/\s+/g,' ').trim());const walker=document.createTreeWalker(h,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const text=node.textContent;if(!text.trim())return;const f=document.createDocumentFragment();text.split(/(\s+)/).forEach(word=>{if(!word)return;if(/^\s+$/.test(word)){f.append(word);return;}const w=document.createElement('fx-w');[...word].forEach(c=>{const l=document.createElement('fx-l');l.textContent=c;l.dataset.c=c;w.append(l);});f.append(w);});node.replaceWith(f);});h.classList.add('fx-focus');});
const layout=()=>heads.forEach(h=>{h.classList.add('fx-measure');const letters=[...h.querySelectorAll('fx-l')];const rects=new Map(letters.map(l=>[l,l.getBoundingClientRect()]));h.classList.remove('fx-measure');const lines=new Map();letters.forEach(l=>{const r=rects.get(l),k=Math.round((r.top+r.bottom)/2/Math.max(8,r.height*.6));(lines.get(k)||lines.set(k,[]).get(k)).push(l);});let n=0;lines.forEach(row=>{const L=Math.min(...row.map(l=>rects.get(l).left)),R=Math.max(...row.map(l=>rects.get(l).right)),W=Math.max(1,R-L),fs=[.62,.68,.58,.65][n++%4];row.forEach(l=>{const r=rects.get(l);l.style.setProperty('--lx',(r.left-L).toFixed(1)+'px');l.style.setProperty('--lw',W.toFixed(1)+'px');l.style.setProperty('--fs',(fs*100)+'%');});});});
let rt;const run=()=>{cancelAnimationFrame(rt);rt=requestAnimationFrame(layout);};run();document.fonts&&document.fonts.ready.then(run);addEventListener('load',run);addEventListener('resize',run);})();
